/* ui/queue.js — part of the universal player. Generated by the one-off split;
 * every top-level name lives on the shared context P (see context.js). */
import { P } from "../context.js";

export function install(P) {


  function renderQueue() {
    if (!P.queuePanel) return;
    const list = P.$("playerQueueList");
    const empty = P.$("playerQueueEmpty");
    const count = P.$("playerQueueCount");
    const total = P.state.queue.length;
    if (count) {
      count.textContent = String(total);
      count.hidden = total === 0;
    }
    if (empty) empty.hidden = total > 0;
    if (!list) return;
    list.replaceChildren();
    P.state.queue.forEach((item, index) => {
      const li = document.createElement("li");
      li.className = "player-queue-item";

      const play = document.createElement("button");
      play.type = "button";
      play.className = "player-queue-play";
      play.dataset.queuePlay = String(index);
      play.setAttribute("aria-label", P.pt("playNext", { title: item.title }));
      const title = document.createElement("span");
      title.className = "player-queue-title";
      title.textContent = item.title;
      const album = document.createElement("span");
      album.className = "player-queue-album";
      album.textContent = `${index + 1}. ${item.albumTitle || ""}`;
      play.append(title, album);

      const remove = document.createElement("button");
      remove.type = "button";
      remove.className = "player-btn player-queue-remove";
      remove.dataset.queueRemove = String(index);
      remove.setAttribute("aria-label", P.pt("removeQueue", { title: item.title }));
      remove.textContent = "×";

      li.append(play, remove);
      list.appendChild(li);
    });
  }

  function openQueue() {
    if (P.programLocked || !P.queuePanel) return;
    if (P.settingsPanel && !P.settingsPanel.hidden) P.closeSettings();
    if (P.queueTimer) { window.clearTimeout(P.queueTimer); P.queueTimer = 0; }
    P.queuePanel.hidden = false;
    P.queueToggle?.setAttribute("aria-expanded", "true");
    P.renderQueue();
    document.body.classList.add("player-queue-open");
    void P.queuePanel.offsetWidth;
    P.queuePanel.classList.add("is-open");
    P.$("playerQueueClose")?.focus({ preventScroll: true });
  }

  function closeQueue() {
    if (!P.queuePanel || P.queuePanel.hidden) return;
    P.queueToggle?.setAttribute("aria-expanded", "false");
    P.queuePanel.classList.remove("is-open");
    document.body.classList.remove("player-queue-open");
    if (P.queueTimer) window.clearTimeout(P.queueTimer);
    P.queueTimer = window.setTimeout(() => {
      if (!P.queuePanel.classList.contains("is-open")) P.queuePanel.hidden = true;
      P.queueTimer = 0;
    }, 280);
  }

  function toggleQueue() {
    P.queuePanel?.hidden ? P.openQueue() : P.closeQueue();
  }
  Object.assign(P, { renderQueue, openQueue, closeQueue, toggleQueue });
}
